<?php
namespace App\Models; use App\Core\Model; class Fund extends Model{protected string $table='funds'; public function create(array $d):int{$s=$this->db()->prepare('INSERT INTO funds(name,code,description,monthly_amount,member_count,duration_months,start_date,end_date,status,rules,exclude_debtors_from_draw) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$d['name'],$d['code'],$d['description']??null,$d['monthly_amount'],$d['member_count'],$d['duration_months'],$d['start_date'],$d['end_date'],$d['status']??'active',$d['rules']??null,!empty($d['exclude_debtors_from_draw'])]);return (int)$this->db()->lastInsertId();}}
